import { field, textarea, select, checkbox, htmlEscape } from "../tool-core.js";export default {form: `<div class="field-grid">${field({ id: "upPattern", label: "URLPattern pattern", value: "/books/:id", help: "Pathname pattern with :named groups, * wildcards, or full URL pattern" })}</div><div class="field-grid">${textarea({ id: "upTestUrls", label: "Test URLs (one per line)", value: "https://example.com/books/123\nhttps://example.com/books/456/chapters\nhttps://example.com/authors\n/books/789", full: true })}</div>`,generate(root) {const patternStr = root.querySelector("#upPattern").value.trim() || "/books/:id";const testUrlsRaw = root.querySelector("#upTestUrls").value.trim();const testUrls = testUrlsRaw ? testUrlsRaw.split("\n").filter(Boolean).map(u => u.trim()) : ["/books/123"];const lines = [];lines.push("// URLPattern Tester — Baseline 2025");lines.push("// Pattern matching for URLs with named groups, wildcards, and regexp.");lines.push("// Browser support: Chrome 95+, Edge 95+, Safari 15.4+, Firefox ✗ (planned)");lines.push("");lines.push(`const pattern = new URLPattern('${patternStr}');`);lines.push("");const results = [];testUrls.forEach(url => {const base = url.startsWith("http") ? url : `https://example.com${url.startsWith("/") ? url : "/" + url}`;let parsedUrl;try {parsedUrl = new URL(base);} catch {parsedUrl = { pathname: url, href: url };}lines.push(`// Test: ${url}`);lines.push(`const result_${testUrls.indexOf(url)} = pattern.test('${base}');`);lines.push("");results.push({ url, base, parsedUrl });});lines.push("// Full match (with groups extraction)");lines.push(`const fullMatch = new URLPattern('${patternStr}').exec('${testUrls[0]}');`);lines.push("if (fullMatch) {");lines.push(" console.log(fullMatch.pathname.groups);");lines.push("}");lines.push("");lines.push("// Pattern syntax reference:");lines.push("// :name — named group, matches up to / or end");lines.push("// * — wildcard, matches zero or more characters");lines.push("// ** — greedy wildcard, matches across / boundaries");lines.push("// (regexp) — custom regular expression group (e.g., :id(\\d+))");lines.push("// {/en}? — optional group (the /en part is optional)");let hasFullPattern = true;try { new URLPattern(patternStr); } catch { hasFullPattern = false; }const rows = results.map((r, i) => {let matches = false;let groups = "";if (hasFullPattern) {try {const p = new URLPattern(patternStr);const execResult = p.exec(r.base);matches = !!execResult;if (matches && execResult.pathname && execResult.pathname.groups) {groups = Object.entries(execResult.pathname.groups).map(([k, v]) => `${k}: ${v || "(empty)"}`).join(", ");}} catch { matches = false; }}return `<tr><td style="padding:6px 10px;font-family:monospace;font-size:12px;word-break:break-all">${r.url}</td><td style="padding:6px 10px;text-align:center"><span style="display:inline-block;width:8px;height:8px;border-radius:50%;background:${matches ? "#22c55e" : "#ef4444"}"></span>${matches ? '<span style="color:#15803d;font-weight:600;font-size:12px">Match</span>' : '<span style="color:#dc2626;font-size:12px">No match</span>'}</td><td style="padding:6px 10px;font-family:monospace;font-size:11px;color:#6b7280">${groups || "—"}</td></tr>`;}).join("");const preview = `<div style="border:1px solid #e5e7eb;border-radius:10px;overflow:hidden"><div style="background:#f9fafb;padding:10px 14px;border-bottom:1px solid #e5e7eb;font-size:13px;font-weight:600;color:#374151">Pattern: <code style="background:#f3f4f6;padding:2px 6px;border-radius:3px">${patternStr}</code>${hasFullPattern ? '<span style="color:#15803d;font-size:12px;margin-left:8px">&#10003; Valid</span>' : '<span style="color:#dc2626;font-size:12px;margin-left:8px">&#10007; Invalid pattern</span>'}</div><table style="width:100%;border-collapse:collapse"><thead><tr style="background:#f9fafb;border-bottom:1px solid #e5e7eb;font-size:11px;color:#6b7280;text-transform:uppercase"><th style="padding:6px 10px;text-align:left">Test URL</th><th style="padding:6px 10px;text-align:center;width:80px">Result</th><th style="padding:6px 10px;text-align:left">Groups</th></tr></thead><tbody>${rows}</tbody></table></div>`;return { output: lines.join("\n"), preview };}};